package com.ruoyi.paiflow.service;
import com.alibaba.fastjson2.*;
import com.ruoyi.paiflow.domain.RunRecord;
import com.ruoyi.paiflow.mapper.*;
import java.util.*;
import org.springframework.stereotype.Service;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.beans.factory.ObjectProvider;
import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;
import org.springframework.transaction.annotation.*;
import org.springframework.transaction.support.TransactionSynchronizationManager;
import static com.ruoyi.paiflow.service.ModelOperationJson.error;
/** 逐次工具准入、唯一派发和原Link回执；外部发送不持有中心事务。 */
@Service @ConditionalOnProperty(prefix="paiflow",name={"enabled","tools.enabled"},havingValue="true")
public class ToolOperationService {
 public record Outcome(JSONObject response,String failureKind,boolean sendAttempted) {}
 public interface Producer {Outcome invoke(ToolRuntimeCatalog.Fixed fixed,long actor,JSONObject payload);default Outcome invoke(ToolRuntimeCatalog.Fixed f,long actor,JSONObject payload,java.util.function.BooleanSupplier active){if(!active.getAsBoolean())return new Outcome(null,"authorization",false);return invoke(f,actor,payload);}}
 public record Reservation(Map<String,Object> row,boolean created) {}
 private final ToolMapper mapper;private final RunMapper runs;private final SpaceMapper spaces;private final RunLeaseService leases;private final ToolRuntimeCatalog catalog;
 private ObjectProvider<ToolOperationService> selves;private ObjectProvider<Producer> producers;private CompletedOutputSources completedSources;
 public ToolOperationService(ToolMapper m,RunMapper r,SpaceMapper s,RunLeaseService l,ToolRuntimeCatalog c){mapper=m;runs=r;spaces=s;leases=l;catalog=c;}
 @Autowired public void usePorts(ObjectProvider<ToolOperationService> s,ObjectProvider<Producer> p){selves=s;producers=p;}
 @Autowired public void useCompletedSources(CompletedOutputSources sources){completedSources=sources;}
 private ToolOperationService self(){var s=selves==null?null:selves.getIfAvailable();if(s==null)throw error("工具事务入口未装配",503);return s;}
 private Producer producer(){var p=producers==null?null:producers.getIfAvailable();if(p==null)throw error("工具受控Producer尚未装配",503);return p;}
 private static JSONObject task(RunRecord run){return ModelMessageSources.sourceObject(run.getAssignmentJson());}
 private RunRecord current(String id,WorkerIdentityService.Principal worker,JSONObject request,boolean active){var before=runs.find(id);if(before==null)throw error("运行不存在",404);if(spaces.lock(before.getSpaceId())==null)throw error("运行空间不存在",403);var run=active?leases.requireActiveLease(id,worker,request.getString("leaseId"),RunLeaseService.attempt(request)):leases.lockWorkerRun(id,worker,request.getString("leaseId"),RunLeaseService.attempt(request));if(!Objects.equals(before.getSpaceId(),run.getSpaceId())||!Set.of("python","java").contains(run.getEngineProfile())||!Objects.equals(run.getEngineProfile(),task(run).get("engineProfile")))throw error("工具运行绑定失效",409);if("java".equals(run.getEngineProfile())){if(!DslCodec.V2.equals(task(run).getOrDefault("executionCodec",DslCodec.V2)))throw error("Java工具不是固定V2运行",409);JavaToolGraphPolicy.validate(task(run).getJSONObject("dsl"));}RunLeaseService.requireExecutionBegun(run);if(active&&!"RUNNING".equals(run.getState()))throw error("运行不能继续工具调用",410);return run;}
 public Set<String> admit(long space,long owner,JSONObject resources,JSONObject execution){return admit(space,owner,resources,execution,"python");} public Set<String> admit(long space,long owner,JSONObject resources,JSONObject execution,String engine){if("java".equals(engine))JavaToolGraphPolicy.validate(execution);else if(!"python".equals(engine))throw error("固定工具引擎无效",409);producer();self();var result=new LinkedHashSet<String>();for(Object raw:execution.getJSONArray("nodes")){var n=(JSONObject)raw;if(!"plugin".equals(com.ruoyi.paiflow.domain.NodeCatalog.typeOf(n.getString("id"))))continue;var p=n.getJSONObject("data").getJSONObject("nodeParam");String resource=p.getString("toolResourceId");var d=resources.getJSONObject(resource);var f=catalog.resolvePinned(space,owner,resource,d);String op="read".equals(f.descriptor().get("effectClass"))?"tools.read":"tools.invoke";result.add(op);}return result;}
 @Transactional(rollbackFor=Exception.class,isolation=Isolation.READ_COMMITTED)
 public JSONObject resource(String id,WorkerIdentityService.Principal worker,String resource,JSONObject request){RunJsonBoundary.fields(request,Set.of("leaseId","attempt"),Set.of());var run=current(id,worker,request,true);var d=task(run).getJSONObject("resourceSnapshots").getJSONObject(resource);var f=catalog.resolvePinned(run.getSpaceId(),run.getOwnerUserId(),resource,d);return f.descriptor();}
 public JSONObject start(String id,WorkerIdentityService.Principal worker,JSONObject request){if(TransactionSynchronizationManager.isActualTransactionActive())throw error("工具派发不能持有数据库事务",500);producer();var reservation=self().reserve(id,worker,request);if(!reservation.created())return ack(reservation.row());var row=reservation.row();Outcome outcome;
  try{var f=self().prepare(id,worker,request,row.get("id").toString());outcome=producer().invoke(f,((Number)row.get("owner")).longValue(),request.getJSONObject("parameters").getJSONObject("legacyPayload"),()->{try{self().prepare(id,worker,request,row.get("id").toString());return true;}catch(RuntimeException e){return false;}});}catch(RuntimeException e){outcome=new Outcome(null,"authorization",false);}return self().finish(row.get("id").toString(),outcome);}
 @Transactional(rollbackFor=Exception.class,isolation=Isolation.READ_COMMITTED)
 public Reservation reserve(String id,WorkerIdentityService.Principal worker,JSONObject request){RunJsonBoundary.fields(request,Set.of("leaseId","attempt","nodeId","operation","parameters","idempotencyKey"),Set.of("iterationId"));RunJsonBoundary.check(request,2*1024*1024);var run=current(id,worker,request,true);var t=task(run);String nodeId=ToolSchema.text(request.get("nodeId"),255,"nodeId");if(request.get("iterationId")!=null)throw error("工具嵌套实例尚未接通",503);var node=DataWorkerOperationService.find(t.getJSONObject("dsl"),nodeId);if(node==null||!"plugin".equals(com.ruoyi.paiflow.domain.NodeCatalog.typeOf(nodeId)))throw error("工具操作不属于固定插件节点",403);
  var params=request.getJSONObject("parameters");RunJsonBoundary.fields(params,Set.of("resourceId","resourceVersion","kind","provider","legacyPayload","resourceBindings"),Set.of());String resource=node.getJSONObject("data").getJSONObject("nodeParam").getString("toolResourceId");var d=t.getJSONObject("resourceSnapshots").getJSONObject(resource);ToolNodeCompiler.descriptor(resource,d);if(!Objects.equals(resource,params.get("resourceId"))||!Objects.equals(d.get("version"),params.get("resourceVersion"))||!"tool".equals(params.get("kind"))||!"spark-link".equals(params.get("provider"))||!(params.get("resourceBindings") instanceof JSONObject bindings)||!bindings.isEmpty())throw error("工具操作与固定资源不一致",409);
  var fixed=catalog.resolvePinned(run.getSpaceId(),run.getOwnerUserId(),resource,d);var profile=catalog.profile(fixed,run.getOwnerUserId());String operation="read".equals(d.get("effectClass"))?"tools.read":"tools.invoke";var policy=t.getJSONObject("effectPolicy");if(!Objects.equals(operation,request.get("operation"))||!policy.getJSONArray("allowedOperations").contains(operation)||"tools.invoke".equals(operation)&&!"approved_write".equals(policy.get("mode")))throw error("工具用途未获运行准入",403);
  var rows=runs.eventsThrough(id,0,run.getLastEventSeq(),1001);if(rows.size()>1000)throw error("工具输入来源事件超过预算",503);var events=new JSONArray();for(var event:rows){var value=ModelMessageSources.sourceObject(event.eventJson());if(Objects.equals(id,value.get("runId"))&&value.getLongValue("seq")==event.seq()&&Objects.equals(run.getAttempt(),value.getInteger("attempt")))events.add(value);}if(completedSources==null)throw error("工具完成输出来源校核未装配",503);var verifiedInputs=completedSources.values(run,t.getJSONObject("dsl"),node,events);var expected="java".equals(run.getEngineProfile())?JavaToolSemantics.expected(node,verifiedInputs,d):ToolSchema.expected(node,verifiedInputs,d);var payload=params.getJSONObject("legacyPayload");if(payload==null)throw error("工具原正文缺失",400);ToolSchema.comparePayload(payload,expected);
  String key=ToolSchema.text(request.get("idempotencyKey"),4096,"idempotencyKey"),keyHash=DataRuntimeCatalog.sha(key),requestHash=RunJsonBoundary.hashFull(request);var previous=mapper.request(id,run.getLeaseId(),run.getAttempt(),keyHash);if(previous!=null){if(!key.equals(previous.get("idempotencyKey"))||!requestHash.equals(previous.get("requestHash")))throw error("工具幂等请求正文冲突",409);return new Reservation(previous,false);}
  var calls=mapper.countOperations(id,nodeId);if(calls>0)throw error("固定工具节点已请求，不能换幂等键重做副作用",409);if(mapper.countResourceOperations(id,resource)>=profile.getMaxCalls())throw error("工具调用预算已用尽",429);
  var binding=JSONObject.of("runId",id,"leaseId",run.getLeaseId(),"attempt",run.getAttempt(),"workflowVersionId",run.getWorkflowVersionId().toString(),"dslHash",t.get("dslHash"),"nodeId",nodeId,"iterationId",null,"operation",operation,"idempotencyKey",key,"kind","tool","provider","spark-link","resourceId",resource,"resourceVersion",d.get("version"),"resourceBindings",new JSONObject());
  var row=new LinkedHashMap<String,Object>();row.put("id","tool-op:"+UUID.randomUUID());row.put("runId",id);row.put("leaseId",run.getLeaseId());row.put("attempt",run.getAttempt());row.put("nodeId",nodeId);row.put("resourceId",resource);row.put("idempotencyKey",key);row.put("requestKeyHash",keyHash);row.put("requestHash",requestHash);row.put("requestJson",request.toJSONString(JSONWriter.Feature.WriteMapNullValue));row.put("bindingJson",binding.toJSONString(JSONWriter.Feature.WriteMapNullValue));row.put("state","RUNNING");row.put("revision",0L);row.put("dispatchStarted",1);row.put("owner",run.getOwnerUserId());if(mapper.insertOperation(row)!=1)throw error("工具操作保存失败",500);return new Reservation(row,true);}
 @Transactional(rollbackFor=Exception.class,isolation=Isolation.READ_COMMITTED)
 public ToolRuntimeCatalog.Fixed prepare(String id,WorkerIdentityService.Principal worker,JSONObject request,String operation){var run=current(id,worker,request,true);var row=mapper.operation(operation);if(row==null||!"RUNNING".equals(row.get("state"))||!Objects.equals(id,row.get("runId"))||!Objects.equals(run.getLeaseId(),row.get("leaseId"))||run.getAttempt()!=((Number)row.get("attempt")).intValue()||!Objects.equals(RunJsonBoundary.hashFull(request),row.get("requestHash")))throw error("工具操作不可派发或固定正文/租约改变",409);var params=request.getJSONObject("parameters");return catalog.resolvePinned(run.getSpaceId(),run.getOwnerUserId(),params.getString("resourceId"),task(run).getJSONObject("resourceSnapshots").getJSONObject(params.getString("resourceId")));}
 @Transactional(rollbackFor=Exception.class,isolation=Isolation.READ_COMMITTED)
 public JSONObject finish(String operation,Outcome outcome){var row=mapper.operation(operation);if(row==null)throw error("工具操作不存在",404);if(!"RUNNING".equals(row.get("state")))return ack(row);String state="FAILED",kind=outcome.failureKind();if(outcome.response()!=null){RunJsonBoundary.check(outcome.response(),2*1024*1024);int code=outcome.response().getJSONObject("header").getIntValue("code");state=code==0?"COMPLETED":"FAILED";kind=code==0?null:"provider";row.put("responseJson",outcome.response().toJSONString(JSONWriter.Feature.WriteMapNullValue));}else if(outcome.sendAttempted())state="EFFECT_UNKNOWN";row.put("state",state);row.put("failureKind",kind);save(row);return ack(row);}
 @Transactional(rollbackFor=Exception.class,isolation=Isolation.READ_COMMITTED)
 public JSONObject status(String id,WorkerIdentityService.Principal worker,String operation,JSONObject request){RunJsonBoundary.fields(request,Set.of("leaseId","attempt"),Set.of());var run=current(id,worker,request,false);var row=owned(operation,run);return ack(row);}
 @Transactional(rollbackFor=Exception.class,isolation=Isolation.READ_COMMITTED)
 public JSONObject cancel(String id,WorkerIdentityService.Principal worker,String operation,JSONObject request){RunJsonBoundary.fields(request,Set.of("leaseId","attempt"),Set.of());var run=current(id,worker,request,false);var row=owned(operation,run);if("RUNNING".equals(row.get("state"))){row.put("state","EFFECT_UNKNOWN");row.put("failureKind","cancelled");save(row);}return ack(row);}
 private Map<String,Object> owned(String operation,RunRecord run){var row=mapper.operation(operation);if(row==null||!Objects.equals(row.get("runId"),run.getId())||!Objects.equals(row.get("leaseId"),run.getLeaseId())||((Number)row.get("attempt")).intValue()!=run.getAttempt())throw error("工具操作不属于当前租约",409);var b=JSON.parseObject((String)row.get("bindingJson"));catalog.resolvePinned(run.getSpaceId(),run.getOwnerUserId(),b.getString("resourceId"),task(run).getJSONObject("resourceSnapshots").getJSONObject(b.getString("resourceId")));return row;}
 private void save(Map<String,Object> row){if(mapper.updateOperation(row)!=1)throw error("工具操作版本冲突",409);row.put("revision",((Number)row.get("revision")).longValue()+1);}
 static JSONObject ack(Map<String,Object> row){var b=JSON.parseObject((String)row.get("bindingJson"));b.put("operationId",row.get("id"));b.put("state",row.get("state"));b.put("failureKind",row.get("failureKind"));b.put("legacyResponse",row.get("responseJson")==null?null:JSON.parseObject((String)row.get("responseJson")));b.put("stopped",false);b.put("proofId",null);return b;}
}
